DROP TABLE IF EXISTS `zk_attendance_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `zk_attendance_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `device_id` bigint unsigned DEFAULT NULL,
  `serial_number` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `employee_pin` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `attendance_time` datetime NOT NULL,
  `status` int unsigned DEFAULT NULL,
  `verify_type` int unsigned DEFAULT NULL,
  `work_code` int unsigned DEFAULT NULL,
  `reserved_1` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reserved_2` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `raw_data` text COLLATE utf8mb4_unicode_ci,
  `source` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'zkteco_push',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `zk_attendance_logs_device_id_foreign` (`device_id`),
  KEY `zk_att_logs_sn_pin_time_idx` (`serial_number`,`employee_pin`,`attendance_time`),
  KEY `zk_att_logs_time_idx` (`attendance_time`),
  KEY `zk_att_logs_pin_idx` (`employee_pin`),
  CONSTRAINT `zk_attendance_logs_device_id_foreign` FOREIGN KEY (`device_id`) REFERENCES `zk_devices` (`id`) ON DELETE SET NULL
